import {useEffect,useId,useRef,useState} from 'react';
import {accessToken,checkedConfig,signOut,startSignIn,clearSession} from './auth';
import {BusinessApi,ApiError,needsBusinessSignIn} from './business-api';
import {ReviewView} from './App';
import type {Config,Review} from './types';
import './business.css';
type J=Record<string,any>;
type Lang='en';
type Tab='overview'|'evidence'|'assessment'|'review'|'actions'|'outcomes'|'history';
const date=(v:string)=>new Date(v).toLocaleString('en-US',{timeZone:'Asia/Tokyo'});
const labels:Record<string,string>={QUEUED:'Queued',RUNNING:'Assessing evidence',REVIEW_REQUIRED:'Ready for review',NEEDS_INPUT:'Evidence needs attention',FAILED:'Assessment failed',READY:'Text ready',CONTINUE:'Continue',REVISE:'Revise',STOP:'Stop',EXPAND:'Expand',AFFECTED:'Affected',UNCHANGED:'Unchanged',UNKNOWN:'Unknown — recovery required',PROPOSED:'Proposed — not started',ACTIVE:'Assigned',IN_PROGRESS:'In progress',COMPLETED:'Completed with evidence',NOT_APPLIED:'Not applied',DELEGATION_APPROVED:'Delegation approved — not applied',APPLYING:'Application started',CANARY:'Canary verification',VERIFIED:'Verified and applied',RECOVERED_CLOSED:'Recovered closed',VERIFIED_PREVIOUS_PUBLICATION:'Previous publication remains applied',CANCELLED:'Cancelled',STOP_REQUESTED:'Stop requested — verifying',STOP_UNKNOWN:'Entry closed — AWS result unknown',SUSPENDED_CONFIRMED:'Suspension confirmed',GOVERNANCE:'Governance',VALUE:'Value',MODEL_ROUTING:'Model routing',PORTFOLIO:'Portfolio',GAP:'Gap',RISK:'Risk'};
const word=(s:string,_l:Lang)=>labels[s]||s;
function Status({value,lang}:{value:string;lang:Lang}){return <span className={'business-status '+value.toLowerCase()}>{word(value,lang)}</span>;}
function download(value:unknown,name:string){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="business-field"><span>{label}</span>{children}</label>;}
function EnglishFileField({label,accept,file,onChange,inputRef,help}:{label:string;accept:string;file:File|null;onChange:(file:File|null)=>void;inputRef?:React.RefObject<HTMLInputElement|null>;help?:string}){
  const id=useId(),localRef=useRef<HTMLInputElement>(null),controlRef=inputRef||localRef;
  useEffect(()=>{if(!file&&controlRef.current)controlRef.current.value='';},[file,controlRef]);
  return <div className="business-field"><span id={id}>{label}</span><div className="business-file-control"><input ref={controlRef} className="business-file-native" type="file" accept={accept} aria-labelledby={id} onChange={e=>onChange(e.target.files?.[0]||null)}/><button type="button" className="business-file-button" onClick={()=>controlRef.current?.click()}>Choose file</button><span className="business-file-name" aria-live="polite">{file?.name||'No file selected'}</span></div>{help&&<small>{help}</small>}</div>;
}
export const validIsoDate=(value:string)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const [year,month,day]=value.split('-').map(Number),parsed=new Date(Date.UTC(year,month-1,day));return parsed.getUTCFullYear()===year&&parsed.getUTCMonth()===month-1&&parsed.getUTCDate()===day;};
const safeId=()=>new URLSearchParams(location.hash.slice(1)).get('object')||sessionStorage.getItem('readinessops-object')||'';

export default function BusinessApp(){
  const lang:Lang='en';
  
  useEffect(()=>{document.documentElement.lang='en';},[]);
  const [config,setConfig]=useState<Config|null>(null),[api,setApi]=useState<BusinessApi|null>(null),[signed,setSigned]=useState(false),[loading,setLoading]=useState(true);
  const [objects,setObjects]=useState<J[]>([]),[selected,setSelected]=useState(safeId),[detail,setDetail]=useState<J|null>(null),[tab,setTab]=useState<Tab>('overview');
  const [create,setCreate]=useState(false),[legacy,setLegacy]=useState(false),[legacyData,setLegacyData]=useState<Review|null>(null);
  const [busy,setBusy]=useState(false),[error,setError]=useState(''),[errorCode,setErrorCode]=useState(''),[notice,setNotice]=useState('');
  const active=useRef(selected);active.current=selected;
  const fail=(e:unknown)=>{setError(e instanceof Error?e.message:String(e));setErrorCode(e instanceof ApiError?e.code:'FAILED');if(e instanceof ApiError&&e.status===401)setSigned(false);};
  useEffect(()=>{let live=true;(async()=>{try{
    const r=await fetch('/config.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error('Workspace configuration is unavailable');const c=checkedConfig(await r.json());
    if(!live)return;setConfig(c);const a=new BusinessApi(c);setApi(a);const token=await accessToken(c);
    if(!token||needsBusinessSignIn(token)){if(token)clearSession();setSigned(false);return;}
    setSigned(true);if(a.hasPending())await a.recover();const result=await a.get('/business/objects');if(live)setObjects(result.objects);
  }catch(e){if(live)fail(e);}finally{if(live)setLoading(false);}})();return()=>{live=false;};},[]);
  async function refresh(oid=selected){if(!api)return;const list=await api.get('/business/objects');setObjects(list.objects);if(oid){const data=await api.get('/business/objects/'+oid);if(active.current===oid)setDetail(data);}}
  useEffect(()=>{if(!api||!signed||!selected){setDetail(null);return;}let live=true;setDetail(null);setError('');api.get('/business/objects/'+selected).then(v=>{if(live)setDetail(v);}).catch(e=>{if(live)fail(e);});return()=>{live=false;};},[api,signed,selected]);
  async function perform(job:()=>Promise<any>,success?:string){setBusy(true);setError('');setErrorCode('');setNotice('');try{const result=await job();if(success)setNotice(success);return result;}catch(e){fail(e);return null;}finally{setBusy(false);}}
  function choose(oid:string){setSelected(oid);sessionStorage.setItem('readinessops-object',oid);history.replaceState({},'','/#object='+oid);setCreate(false);setLegacy(false);setTab('overview');setNotice('');}
  async function openLegacy(){setLegacy(true);setCreate(false);setSelected('');if(api&&!legacyData)await perform(async()=>setLegacyData(await api.get('/review')));}
  const header=<header className="business-header"><button className="business-brand" onClick={()=>{setSelected('');setCreate(false);setLegacy(false);sessionStorage.removeItem('readinessops-object');history.replaceState({},'','/');}}><strong>SOLIFAN</strong><span>ReadinessOps <small>AWS</small></span></button><div className="business-header-actions">{signed&&config&&<button onClick={()=>signOut(config)}>{'Sign out'}</button>}</div></header>;
  const problem=error&&<div role="alert" className="business-alert"><p>{error}</p>{signed&&api?.hasPending()&&<button disabled={busy} onClick={()=>perform(async()=>{await api.recover();await refresh();},'Previous operation recovered.')}>{'Recover previous operation'}</button>}{signed&&['STALE_VERSION','ASSESSMENT_STALE','DRAFT_STALE'].includes(errorCode)&&<button disabled={busy} onClick={()=>perform(()=>refresh(),'Latest records loaded.')}>{'Reload latest records'}</button>}{errorCode==='SCOPE_REQUIRED'&&config&&<button onClick={()=>startSignIn(config)}>{'Sign in again with the same account'}</button>}</div>;
  if(loading)return <>{header}<main className="business-login"><p role="status">{'Opening your workspace.'}</p></main></>;
  if(!signed)return <>{header}<main className="business-login"><p className="business-kicker">EVIDENCE. JUDGMENT. NEXT STEPS.</p><h1>{'From a business question\nto a decision you can use.'}</h1><p>{'Bring your evidence, examine the findings, and record a considered human decision. Reassess it when the evidence changes.'}</p>{problem}<button className="business-primary" onClick={()=>config&&startSignIn(config)}>{'Sign in to begin'}</button><small>{'Use your existing workspace username and password.'}</small></main></>;
  return <>{header}<div className="business-shell"><aside className="business-sidebar"><p className="business-kicker">{'YOUR BUSINESS OBJECTS'}</p><button className="business-new" onClick={()=>{setCreate(true);setLegacy(false);setSelected('');}}>{'＋ Add business object'}</button><nav aria-label={'Business objects'}>{objects.map(o=><button key={o.object_id} aria-current={selected===o.object_id?'page':undefined} onClick={()=>choose(o.object_id)}><span>{o.name}</span><small>{o.published_current?'Published':'In review'}</small></button>)}</nav><button className="business-legacy-link" onClick={openLegacy}>{'Explore the saved AWS proof'} <span>↗</span></button><div className="business-sidebar-note">{'Keep the reasoning with the work.'}</div></aside>
  <main className="business-main">{problem}{notice&&<div className="business-notice" role="status">{notice}</div>}
    {legacy?<><div className="business-page-title"><p className="business-kicker">AWS · AUTHORITY DELTA</p><h1>{'Saved technical proof'}</h1><p>{'Analysis and authorization for a fixed sample, retained separately from your business approvals.'}</p></div>{legacyData?<ReviewView data={legacyData}/>:<p role="status">{'Loading saved evidence.'}</p>}</>:
    create?<CreateObject lang={lang} busy={busy} onCreate={body=>perform(async()=>{const r=await api!.post('/business/objects',body);const list=await api!.get('/business/objects');setObjects(list.objects);choose(r.object_id);setTab('evidence');})}/>:
    selected?detail?<ObjectWorkspace detail={detail} api={api!} lang={lang} tab={tab} setTab={setTab} busy={busy} perform={perform} refresh={()=>refresh()} onError={fail}/>:<p role="status">{'Loading business records.'}</p>:
    <><div className="business-page-title"><p className="business-kicker">READINESSOPS · WORKSPACE</p><h1>{'What will you move forward, and why?'}</h1><p>{'Start with a business question. Use evidence to build and review your decision.'}</p></div><section className="business-welcome"><div><span className="business-step-number">01</span><h2>{'Start with a business object'}</h2><p>{'For example: which support tasks can we delegate to AI? Can we share this customer data externally?'}</p><button className="business-primary" onClick={()=>setCreate(true)}>{'Add a business question'}</button></div><ol>{['Set the question and purpose','Assess the evidence and gaps','Review and approve','Publish the official decision'].map((s,i)=><li key={s}><span>{String(i+1).padStart(2,'0')}</span>{s}</li>)}</ol></section>{objects.length>0&&<section className="business-card"><h2>{'Your work'}</h2>{objects.map(o=><button className="business-object-row" key={o.object_id} onClick={()=>choose(o.object_id)}><span><strong>{o.name}</strong><small>{o.question}</small></span><span>→</span></button>)}</section>}</>}
    <footer className="business-footer"><span>ReadinessOps · SOLIFAN</span><span>{'Evidence analysis: Amazon Nova Pro (APAC). TXT, text PDF and JSON supported.'}</span></footer>
  </main></div></>;
}

export function CreateObject({lang,busy,onCreate}:{lang:Lang;busy:boolean;onCreate:(v:J)=>void}){
  const [form,setForm]=useState({name:'',purpose:'',question:'',owner:'',goals:''});
  function field(key:keyof typeof form,label:string,placeholder:string,multiline=false){return <Field label={label}>{multiline?<textarea required={key!=='goals'} maxLength={key==='question'?4000:1600} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})} placeholder={placeholder}/>:<input required maxLength={160} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})} placeholder={placeholder}/>}</Field>;}
  return <><div className="business-page-title"><p className="business-kicker">01 · BUSINESS CONTEXT</p><h1>{'The work, and the question.'}</h1><p>{'A specific question helps focus the evidence review.'}</p></div><form className="business-card business-form" onSubmit={e=>{e.preventDefault();onCreate(form);}}><div className="business-form-grid">{field('name','Business / initiative name','Example: external customer data sharing')}{field('owner','Responsible person','Person or team')}</div>{field('purpose','Business purpose','What do you want to achieve?',true)}{field('question','Question to assess','Under what conditions can this work proceed?',true)}{field('goals','Goal / measurement (optional)','Example: review time, quality or cost; include a baseline if known.',true)}<div className="business-form-footer"><p>{'Next, add the evidence supporting this review.'}</p><button className="business-primary" disabled={busy}>{busy?'Saving…':'Create and add evidence'}</button></div></form></>;
}

export function ObjectWorkspace({detail,api,lang,tab,setTab,busy,perform,refresh,onError}:{detail:J;api:BusinessApi;lang:Lang;tab:Tab;setTab:(t:Tab)=>void;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>;onError:(e:unknown)=>void}){
  const o=detail.object,base='/business/objects/'+o.object_id;
  const [run,setRun]=useState<J|null>(null),[runId,setRunId]=useState(o.latest_run||'');
  useEffect(()=>{setRunId(o.latest_run||'');},[o.object_id,o.latest_run]);
  useEffect(()=>{setRun(null);if(!runId){return;}let live=true,timer:number;async function poll(){try{const r=await api.get(base+'/runs/'+runId);if(!live)return;setRun(r);if(['QUEUED','RUNNING'].includes(r.status))timer=window.setTimeout(poll,3000);}catch(e){if(live)onError(e);}}void poll();return()=>{live=false;clearTimeout(timer);};},[runId,base]);
  useEffect(()=>{if(!['APPLYING','CANARY','UNKNOWN'].includes(o.latest_application?.status)&&!['STOP_REQUESTED','UNKNOWN'].includes(o.authority_control?.status))return;let live=true,timer:number;async function poll(){try{await refresh();}catch(e){if(live)onError(e);}if(live)timer=window.setTimeout(poll,3000);}timer=window.setTimeout(poll,3000);return()=>{live=false;clearTimeout(timer);};},[o.object_id,o.latest_application?.application_id,o.latest_application?.status,o.authority_control?.status]);
  const tabs:[Tab,string][]=[['overview','Overview'],['evidence','Evidence'],['assessment','Assessment'],['review','Review & publish'],['actions','Actions'],['outcomes','Outcomes & exchange'],['history','History']];
  return <><div className="business-object-heading"><div><p className="business-kicker">{o.owner}</p><h1>{o.name}</h1></div><span className="business-version">{o.published_current?'Published decision':'Not published'}</span></div><nav className="business-tabs" aria-label={'Business workflow'}>{tabs.map(([id,label])=><button key={id} aria-current={id===tab?'page':undefined} onClick={()=>setTab(id)}>{label}</button>)}</nav>
  {tab==='overview'&&<><section className="business-card"><p className="business-kicker">{'THE QUESTION'}</p><h2 className="business-question">{o.question}</h2><div className="business-context-grid"><div><h3>{'Purpose'}</h3><p>{o.purpose}</p></div><div><h3>{'Goal / measurement'}</h3><p>{o.goals||'Not specified yet.'}</p></div></div><button className="business-primary" onClick={()=>setTab(detail.evidence.length?'assessment':'evidence')}>{detail.evidence.length?'Open assessment':'Add supporting evidence'}</button></section><section className="business-card"><p className="business-kicker">{'OFFICIAL DECISION'}</p>{detail.official_decision?<><h2>{detail.official_decision.proposal.summary}</h2><p className="business-muted">{date(o.published_current.at)} · {o.published_current.publisher_name}</p><div className="business-decision-grid">{detail.official_decision.proposal.decision_items.map((i:J)=><div key={i.perspective}><h3>{word(i.perspective,lang)}</h3><Status value={i.recommendation} lang={lang}/><p>{i.rationale}</p></div>)}</div></>:<><h2>{'Your published decision will appear here.'}</h2><p>{'Generating an assessment or approving a draft does not change the official version.'}</p></>}<div className="business-application-state"><span>{'AWS runtime authority'}</span><strong>{word(o.application_status||'NOT_APPLIED',lang)}</strong></div>{o.applied_binding&&<details className="business-details"><summary>{'Verified AppliedBinding'}</summary><dl className="business-binding"><div><dt>Application</dt><dd>{o.applied_binding.application_id}</dd></div><div><dt>Publication</dt><dd>{o.applied_binding.publication_id}</dd></div><div><dt>Connection</dt><dd>{o.applied_binding.connection_id}</dd></div><div><dt>Policy hash</dt><dd>{o.applied_binding.policy_hash}</dd></div></dl></details>}</section></>}
  {tab==='evidence'&&<EvidencePanel detail={detail} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh} onStarted={()=>setTab('assessment')}/>}
  {tab==='assessment'&&<><div className="business-section-heading"><div><h2>{'From evidence to the points that need judgment.'}</h2><p>{'Each assessment uses a fixed question and evidence snapshot. Earlier runs remain available.'}</p></div><button className="business-secondary" onClick={()=>setTab('evidence')}>{'Select evidence to assess'}</button></div>{detail.runs.length>0&&<Field label={'Assessment run'}><select value={runId} onChange={e=>setRunId(e.target.value)}>{detail.runs.map((r:J)=><option key={r.run_id} value={r.run_id}>{date(r.created_at)} · {word(run&&run.run_id===r.run_id?run.status:r.status,lang)}</option>)}</select></Field>}{run?<><section className="business-card"><div className="business-card-heading"><Status value={run.status} lang={lang}/><small>{date(run.created_at)}</small></div>{['QUEUED','RUNNING'].includes(run.status)?<div className="business-progress" role="status"><span className="business-spinner"/><h2>{'Reading the evidence and preparing a supported assessment.'}</h2><p>{'You can leave this screen. Return to find this same assessment and its result.'}</p></div>:run.analysis?.proposal?<><h2>{run.analysis.proposal.summary}</h2><AssessmentContent proposal={run.analysis.proposal} evidence={detail.evidence} lang={lang}/>{runId===o.latest_run&&<button className="business-primary" onClick={()=>{void refresh();setTab('review');}}>{'Review the proposed decision'}</button>}</>:<><h2>{'The assessment could not be completed.'}</h2><p>{run.error||'This assessment did not produce a supported proposal.'}</p><button className="business-secondary" onClick={()=>setTab('evidence')}>{'Review evidence and reassess'}</button></>}{<details className="business-details"><summary>{'Assessment record'}</summary><p>{run.analysis?.model_id||'Amazon Nova Pro'} · {run.analysis?.model_calls?.length||0} model calls</p><button onClick={()=>download(run,'ReadinessOps_Assessment.json')}>{'Download assessment'}</button></details>}</section></>:<section className="business-empty"><h2>{'No assessment has started.'}</h2><p>{'Add evidence and choose the documents for your assessment.'}</p></section>}</>}
  {tab==='review'&&<ReviewPanel detail={detail} run={runId===o.latest_run&&run?.run_id===runId?run:null} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh} goAssessment={()=>setTab('assessment')} goOverview={()=>{setTab('overview');window.scrollTo(0,0);}} goHistory={()=>{setTab('history');window.scrollTo(0,0);}}/>}
  {tab==='actions'&&<ActionTracker detail={detail} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh} goEvidence={()=>setTab('evidence')}/>}
  {tab==='outcomes'&&<OutcomeExchange detail={detail} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh}/>}
  {tab==='history'&&<><div className="business-section-heading"><div><h2>{'Keep the reasoning with the record.'}</h2><p>{'Evidence additions, assessments, human decisions and publications remain available.'}</p></div><button className="business-secondary" disabled={busy} onClick={()=>void perform(async()=>download(await api.get(base+'/acceptance-evidence'),'ReadinessOps_Acceptance_Evidence_'+o.object_id+'.json'),'Verified acceptance evidence downloaded.')}>{'Download acceptance evidence'}</button></div><section className="business-card">{detail.history.map((e:J)=><article className="business-history-row" key={e.event_id}><span className="business-history-dot"/><div><strong>{({OBJECT_CREATED:'Business object created',EVIDENCE_ADDED:'Evidence added',ASSESSMENT_QUEUED:'Assessment queued',DECISION_DRAFT_SAVED:'Decision draft saved',HUMAN_APPROVE:'Human approval recorded',HUMAN_REJECT:'Human rejection recorded',HUMAN_RETURN:'Returned for revision',DECISION_PUBLISHED:'Official decision published',ACTION_ACTIVATED:'Action assigned with a due date',ACTION_IN_PROGRESS:'Action moved in progress',ACTION_COMPLETED:'Action completed with resolution evidence',ACTION_CANCELLED:'Action cancelled',AWS_DELEGATION_APPROVED:'AWS delegation separately approved',AWS_APPLICATION_STARTED:'AWS application started',AWS_AUTHORITY_STOP_REQUESTED:'AWS authority stop requested'} as J)[e.kind]||e.kind}</strong><small>{date(e.at)} · {e.actor_name}</small>{(e.details.note||e.details.reason||e.details.title)&&<p>{e.details.note||e.details.reason||e.details.title}</p>}<details className="business-details"><summary>{'Record references'}</summary><pre>{JSON.stringify(e.details,null,2)}</pre></details></div></article>)}</section></>}
  </>;
}

export function ActionTracker({detail,api,lang,busy,perform,refresh,goEvidence}:{detail:J;api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>;goEvidence:()=>void}){
 const records:J[]=detail.action_records||[];
 return <><div className="business-section-heading"><div><h2>{'Turn proposed actions into accountable work.'}</h2><p>{'AI-proposed actions remain unstarted at publication. Assign an owner and due date, then attach new resolution evidence before completion.'}</p></div><button className="business-secondary" onClick={goEvidence}>{'Add resolution evidence'}</button></div>{records.length?<div className="business-action-tracker">{records.map(action=><ActionCard key={action.action_id} action={action} object={detail.object} evidence={detail.evidence} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh}/>)}</div>:<section className="business-empty"><h2>{'No published action proposals yet.'}</h2><p>{'Assessment suggestions appear here as unstarted actions only after human approval and explicit publication.'}</p></section>}</>;
}

function ActionCard({action,object,evidence,api,lang,busy,perform,refresh}:{action:J;object:J;evidence:J[];api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>}){
 const terminal=['COMPLETED','CANCELLED'].includes(action.status);
 const options=action.status==='PROPOSED'?['ACTIVE','CANCELLED']:terminal?[]:['ACTIVE','IN_PROGRESS','COMPLETED','CANCELLED'];
 const initialStatus=terminal?action.status:(action.status==='PROPOSED'?'ACTIVE':action.status);
 const [status,setStatus]=useState(initialStatus),[owner,setOwner]=useState(action.owner||object.owner||''),[due,setDue]=useState(action.due_on||''),[reason,setReason]=useState(''),[selected,setSelected]=useState<string[]>([]);
 useEffect(()=>{const next=action.status==='PROPOSED'?['ACTIVE','CANCELLED']:['ACTIVE','IN_PROGRESS','COMPLETED','CANCELLED'];setStatus(terminal?action.status:(next.includes(action.status)?action.status:next[0]));setOwner(action.owner||object.owner||'');setDue(action.due_on||'');setReason('');setSelected([]);},[action.record_revision]);
 const available=evidence.filter(e=>e.extraction_status==='READY'&&!action.baseline_evidence_ids.includes(e.evidence_id));
 const invalid=!reason.trim()||(status!=='CANCELLED'&&(!owner.trim()||!validIsoDate(due)))||(status==='COMPLETED'&&selected.length===0);
 async function save(){await perform(async()=>{await api.post('/business/objects/'+object.object_id+'/actions/'+action.action_id,{expected_revision:object.record_revision,expected_action_revision:action.record_revision,status,owner,due_on:due,reason,resolution_evidence_ids:status==='COMPLETED'?selected:[]});await refresh();},status==='COMPLETED'?'Action completion was recorded with resolution evidence. It will be linked to the next reassessment.':'Action status saved.');}
 return <section className="business-card business-action-card"><div className="business-card-heading"><div><p className="business-kicker">{action.action_id}</p><h3>{action.title}</h3></div><Status value={action.status} lang={lang}/></div><p>{action.description}</p><dl className="business-binding"><div><dt>{'Related findings'}</dt><dd>{action.finding_ids.join(', ')}</dd></div><div><dt>{'Publication'}</dt><dd>{action.publication_id}</dd></div>{action.owner&&<div><dt>{'Owner'}</dt><dd>{action.owner}</dd></div>}{action.due_on&&<div><dt>{'Due'}</dt><dd>{action.due_on}</dd></div>}{action.reassessment_run_id&&<div><dt>{'Reassessment'}</dt><dd>{action.reassessment_run_id}</dd></div>}</dl>{terminal?<><p className="business-muted">{action.status==='COMPLETED'?'Completion is backed by new evidence; the AI proposal alone did not complete it.':'The cancellation reason is retained in history.'}</p>{action.resolution_evidence?.length>0&&<ul className="business-action-evidence">{action.resolution_evidence.map((e:J)=><li key={e.evidence_id}>{e.title} · {e.evidence_id}</li>)}</ul>}</>:<><div className="business-form-grid"><Field label={'Next status'}><select value={status} onChange={e=>{setStatus(e.target.value);setSelected([]);}}>{options.map(v=><option key={v} value={v}>{word(v,lang)}</option>)}</select></Field><Field label={'Owner'}><input maxLength={160} value={owner} disabled={status==='CANCELLED'} onChange={e=>setOwner(e.target.value)}/></Field></div><Field label={'Due date'}><input type="text" inputMode="numeric" autoComplete="off" maxLength={10} pattern="\d{4}-\d{2}-\d{2}" placeholder="YYYY-MM-DD" value={due} disabled={status==='CANCELLED'} onChange={e=>setDue(e.target.value)}/></Field>{status==='COMPLETED'&&<Field label={'New resolution evidence'}><div className="business-action-evidence-choices">{available.length?available.map((e:J)=><label key={e.evidence_id}><input type="checkbox" checked={selected.includes(e.evidence_id)} onChange={v=>setSelected(ids=>v.target.checked?[...ids,e.evidence_id]:ids.filter(id=>id!==e.evidence_id))}/><span>{e.title}</span></label>):<small>{'Add readable evidence that was not part of the original finding first.'}</small>}</div></Field>}<Field label={'Update reason'}><textarea maxLength={1600} value={reason} onChange={e=>setReason(e.target.value)}/></Field><button className="business-primary" disabled={busy||invalid} onClick={()=>void save()}>{status==='COMPLETED'?'Complete with evidence':'Save action status'}</button></>}</section>;
}

export function OutcomeExchange({detail,api,lang,busy,perform,refresh}:{detail:J;api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>}){
 const o=detail.object,base='/business/objects/'+o.object_id;
 const [authorityResult,setAuthorityResult]=useState(''),[businessResult,setBusinessResult]=useState(''),[metricMode,setMetricMode]=useState('NONE');
 const [metricName,setMetricName]=useState(''),[metricValue,setMetricValue]=useState(''),[unit,setUnit]=useState(''),[period,setPeriod]=useState(''),[source,setSource]=useState(''),[basis,setBasis]=useState('OBSERVED'),[missingReason,setMissingReason]=useState(''),[importFile,setImportFile]=useState<File|null>(null);
 const [targetId,setTargetId]=useState('PUBLICATION');
 const current=o.published_current,outcomes:J[]=detail.outcome_records||[],imports:J[]=detail.imported_records||[];
 const applications:J[]=(detail.applications||[]).filter((v:J)=>v.publication_id===current?.publication_id&&['VERIFIED','RECOVERED_CLOSED'].includes(v.status));
 const selectedApplication=applications.find(v=>v.application_id===targetId);
 const target=targetId==='PUBLICATION'&&current?{kind:'DECISION_PUBLICATION',id:current.publication_id,digest:current.digest}:selectedApplication?{kind:'AWS_APPLICATION',id:selectedApplication.application_id,digest:selectedApplication.enforcement_digest}:null;
 useEffect(()=>{setTargetId('PUBLICATION');setAuthorityResult('');},[current?.publication_id]);
 function metrics(){if(metricMode==='NONE')return [];if(metricMode==='NOT_MEASURED')return [{name:metricName,measurement_status:'NOT_MEASURED',source,reason:missingReason}];return [{name:metricName,measurement_status:'MEASURED',value:Number(metricValue),unit,period,source,basis}];}
 const metricInvalid=metricMode!=='NONE'&&(!metricName.trim()||!source.trim()||(metricMode==='MEASURED'&&(!metricValue||!unit.trim()||!period.trim()))||(metricMode==='NOT_MEASURED'&&!missingReason.trim()));
 async function record(){if(!current||!target)return;await perform(async()=>{await api.post(base+'/outcomes',{expected_revision:o.record_revision,target,authority_result:authorityResult,business_result:businessResult,metrics:metrics()});setBusinessResult('');setAuthorityResult('');setMetricMode('NONE');setMetricName('');setMetricValue('');setUnit('');setPeriod('');setSource('');setMissingReason('');await refresh();},'Outcome recorded against the selected record. AWS authority was not changed.');}
 async function exportFixed(){await perform(async()=>download(await api.get(base+'/interchange'),'ReadinessOps_Interchange_'+current.pack_id+'_r'+current.revision+'.json'));}
 async function importFixed(){if(!importFile)return;await perform(async()=>{const document=JSON.parse(await importFile.text());await api.post(base+'/imports',{expected_revision:o.record_revision,document});setImportFile(null);await refresh();},'External document imported as a fixed reference. The official decision and AWS authority were unchanged.');}
 return <><div className="business-section-heading"><div><h2>{'Record outcomes without inventing measurements.'}</h2><p>{'Link an outcome to the official decision or a completed AWS application. Keep unmeasured metrics explicit.'}</p></div>{current&&<button className="business-secondary" disabled={busy} onClick={()=>void exportFixed()}>{'Export fixed version'}</button>}</div>{!current?<section className="business-empty"><h2>{'Publish an official decision before recording outcomes.'}</h2></section>:<section className="business-card business-outcome-form"><p className="business-kicker">OUTCOME</p><Field label={'Record this outcome against'}><select value={targetId} onChange={e=>{setTargetId(e.target.value);setAuthorityResult('');}}><option value="PUBLICATION">{'Current official decision'}</option>{applications.map(v=><option key={v.application_id} value={v.application_id}>AWS application · {word(v.status,lang)} · {v.application_id}</option>)}</select></Field><div className="business-form-grid"><Field label={'Authority result'}><select value={authorityResult} onChange={e=>setAuthorityResult(e.target.value)}><option value="">{'Select the observed result'}</option>{['ALLOW','DENY','ERROR'].filter(v=>v!=='ALLOW'||!selectedApplication||selectedApplication.status==='VERIFIED').map(v=><option key={v}>{v}</option>)}</select></Field><Field label={'Metric'}><select value={metricMode} onChange={e=>setMetricMode(e.target.value)}><option value="NONE">{'No metric'}</option><option value="MEASURED">{'Measured'}</option><option value="NOT_MEASURED">{'Not measured'}</option></select></Field></div><Field label={'Business result'}><textarea maxLength={1600} value={businessResult} onChange={e=>setBusinessResult(e.target.value)}/></Field>{metricMode!=='NONE'&&<><div className="business-form-grid"><Field label={'Metric name'}><input maxLength={160} value={metricName} onChange={e=>setMetricName(e.target.value)}/></Field><Field label={'Source'}><input maxLength={1000} value={source} onChange={e=>setSource(e.target.value)}/></Field></div>{metricMode==='MEASURED'?<><div className="business-form-grid"><Field label={'Value'}><input type="number" step="any" value={metricValue} onChange={e=>setMetricValue(e.target.value)}/></Field><Field label={'Unit'}><input maxLength={80} value={unit} onChange={e=>setUnit(e.target.value)}/></Field></div><div className="business-form-grid"><Field label={'Period'}><input maxLength={160} value={period} onChange={e=>setPeriod(e.target.value)}/></Field><Field label={'Basis'}><select value={basis} onChange={e=>setBasis(e.target.value)}><option value="OBSERVED">{'Observed'}</option><option value="ESTIMATED">{'Estimated'}</option></select></Field></div></>:<Field label={'Why it is not measured'}><textarea maxLength={700} value={missingReason} onChange={e=>setMissingReason(e.target.value)}/></Field>}</>}<button className="business-primary" disabled={busy||!target||!authorityResult||!businessResult.trim()||metricInvalid} onClick={()=>void record()}>{'Record outcome'}</button></section>}
 {outcomes.length>0&&<section className="business-card"><h2>{'Recorded outcomes'}</h2>{outcomes.map(v=><article className="business-outcome-row" key={v.outcome_id}><div><strong>{v.authority_result} · {v.business_result}</strong><small>{date(v.recorded_at)} · {v.outcome_id}</small><small>{v.target.kind==='AWS_APPLICATION'?'AWS application':'Official decision'} · {v.target.id}</small></div>{v.metrics.length?<ul>{v.metrics.map((m:J,i:number)=><li key={i}>{m.name}: {m.measurement_status==='MEASURED'?`${m.value} ${m.unit} · ${m.period} · ${m.basis}`:`Not measured · ${m.reason}`}</li>)}</ul>:<span>{'No metric'}</span>}</article>)}</section>}
 <section className="business-card business-import"><p className="business-kicker">VERSION-FIXED IMPORT</p><h2>{'Import an external Decision Pack and Outcomes as a fixed reference.'}</h2><p>{'The authority source, version and digest are verified. A file import is not Snowflake connectivity and cannot change this object’s official decision or AWS authority.'}</p><EnglishFileField label={'Interchange JSON'} accept="application/json,.json" file={importFile} onChange={setImportFile}/><button className="business-secondary" disabled={busy||!importFile} onClick={()=>void importFixed()}>{'Import fixed reference'}</button>{imports.length>0&&<ul className="business-import-list">{imports.map(v=><li key={v.import_id}>{v.authority_source} · {v.pack_id} r{v.pack_revision} · {v.outcome_count} outcomes</li>)}</ul>}</section></>;
}

function CitationList({items,evidence,lang}:{items:J[];evidence:J[];lang:Lang}){return <div className="business-citations">{items.map((c,i)=><blockquote key={i}><p>{c.quote}</p><cite>{evidence.find(e=>e.evidence_id===c.evidence_id)?.title||c.evidence_id}</cite></blockquote>)}</div>;}
export function ReassessmentPanel({proposal,priorItems,evidence,lang}:{proposal:J;priorItems:J[];evidence:J[];lang:Lang}){
 const comparison=proposal.reassessment;if(!comparison)return null;
 const priority:Record<string,number>={AFFECTED:0,UNKNOWN:1,UNCHANGED:2};
 const candidates=new Map(proposal.decision_items.map((x:J)=>[x.decision_item_id,x]));
 const prior=new Map(priorItems.map((x:J)=>[x.decision_item_id,x]));
 const impacts=[...comparison.impacts].sort((a:J,b:J)=>(priority[a.status]??9)-(priority[b.status]??9));
 return <section className="business-card business-reassessment"><div className="business-reassessment-heading"><div><p className="business-kicker">AUTHORITY DELTA · CHANGE REVIEW</p><h2>{'What changed against the official decision'}</h2></div><span>{impacts.filter((x:J)=>x.status!=='UNCHANGED').length} {'items need attention'}</span></div><p className="business-reassessment-note">{'The official decision has not changed. Its prior approval is not carried to this candidate, and no AWS runtime authority is applied.'}</p><details className="business-details"><summary>{'Compared official record'}</summary><dl className="business-binding"><div><dt>Publication</dt><dd>{comparison.compared_publication_id}</dd></div><div><dt>Decision digest</dt><dd>{comparison.compared_decision_digest}</dd></div></dl></details><div className="business-impact-list">{impacts.map((impact:J)=>{const candidate=candidates.get(impact.decision_item_id) as J|undefined,previous=prior.get(impact.decision_item_id) as J|undefined;return <article className={'business-impact '+impact.status.toLowerCase()} key={impact.decision_item_id}><div className="business-impact-heading"><div><small>{impact.decision_item_id}</small><h3>{word(candidate?.perspective||previous?.perspective||'',lang)}</h3></div><Status value={impact.status} lang={lang}/></div><div className="business-decision-compare"><div><span>{'Official'}</span><strong>{previous?word(previous.recommendation,lang):'Unavailable'}</strong></div><span aria-hidden="true">→</span><div><span>{'Candidate'}</span><strong>{candidate?word(candidate.recommendation,lang):'Unavailable'}</strong></div></div><p>{impact.reason}</p>{impact.unknowns.length>0&&<div className="business-impact-unknown"><strong>{'Unresolved'}</strong><ul>{impact.unknowns.map((x:string,i:number)=><li key={i}>{x}</li>)}</ul></div>}<CitationList items={impact.citations} evidence={evidence} lang={lang}/></article>;})}</div></section>;
}
function AssessmentContent({proposal,evidence,lang}:{proposal:J;evidence:J[];lang:Lang}){return <>{proposal.missing_information.length>0&&<div className="business-missing"><h3>{'Information to confirm'}</h3><ul>{proposal.missing_information.map((s:string,i:number)=><li key={i}>{s}</li>)}</ul></div>}<div className="business-findings">{proposal.findings.map((f:J)=><article key={f.finding_id}><p className="business-kicker">{word(f.kind,lang)} · {f.finding_id}</p><h3>{f.title}</h3><p>{f.description}</p><small>{f.severity_reason}</small><CitationList items={f.citations} evidence={evidence} lang={lang}/></article>)}</div>{proposal.actions.length>0&&<div className="business-actions"><h3>{'Proposed next actions'}</h3>{proposal.actions.map((a:J,i:number)=><div key={i}><strong>{a.title}</strong><p>{a.description}</p></div>)}</div>}</>;}

function EvidencePanel({detail,api,lang,busy,perform,refresh,onStarted}:{detail:J;api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>;onStarted:()=>void}){
 const o=detail.object,base='/business/objects/'+o.object_id;
 const [file,setFile]=useState<File|null>(null),[title,setTitle]=useState(''),[source,setSource]=useState(''),[selected,setSelected]=useState<string[]>(detail.evidence.filter((e:J)=>e.extraction_status==='READY').slice(-8).map((e:J)=>e.evidence_id));
 const input=useRef<HTMLInputElement>(null);
 async function upload(){if(!file)return;await perform(async()=>{if(file.size>2_000_000)throw new Error('Select a file up to 2 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const r=await api.post(base+'/evidence',{expected_revision:o.record_revision,filename:file.name,title:title||file.name,source:source||'User supplied evidence',content_base64:btoa(raw)});setFile(null);setTitle('');if(input.current)input.current.value='';if(r.extraction_status==='READY')setSelected(ids=>[...ids.slice(-7),r.evidence_id]);await refresh();},'Evidence saved. Check the extraction result.');}
 return <><div className="business-section-heading"><div><h2>{'The evidence behind the decision.'}</h2><p>{'Originals and extracted text are retained. New evidence does not overwrite earlier assessments.'}</p></div></div><form className="business-card business-upload" onSubmit={e=>{e.preventDefault();void upload();}}><EnglishFileField label={'Evidence file'} accept=".txt,.pdf,.json" file={file} inputRef={input} onChange={f=>{setFile(f);setTitle(f?.name||'');}} help={'TXT, text PDF or JSON / up to 2 MB per file. Image-only PDFs need a text version.'}/><div className="business-form-grid"><Field label={'Title'}><input maxLength={160} value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label={'Source (optional)'}><input maxLength={1000} value={source} onChange={e=>setSource(e.target.value)} placeholder={'Author, policy name, or source'}/></Field></div><button className="business-primary" disabled={busy||!file}>{busy?'Saving…':'Add evidence'}</button></form>
 {detail.evidence.length>0?<><div className="business-section-heading"><div><h2>{'Choose evidence for the assessment'}</h2><p>{'Select up to eight documents. Their versions are fixed for this assessment.'}</p></div><button className="business-primary" disabled={busy||selected.length===0||selected.length>8} onClick={()=>perform(async()=>{await api.post(base+'/runs',{expected_revision:o.record_revision,evidence_ids:selected});await refresh();onStarted();})}>{'Start assessment'}</button></div>{detail.evidence.map((e:J)=><section className="business-card business-evidence" key={e.evidence_id}><div className="business-card-heading"><label className="business-evidence-choice"><input type="checkbox" disabled={e.extraction_status!=='READY'} checked={selected.includes(e.evidence_id)} onChange={ev=>setSelected(ids=>ev.target.checked?[...ids,e.evidence_id]:ids.filter(id=>id!==e.evidence_id))}/><strong>{e.title}</strong></label><Status value={e.extraction_status} lang={lang}/></div><p className="business-muted">{e.source} · {date(e.ingested_at)}</p>{e.reason&&<p className="business-evidence-problem">{e.reason}</p>}{e.text&&<details className="business-details"><summary>{'Read extracted text'}</summary><pre>{e.text}</pre></details>}<button className="business-text-link" onClick={()=>perform(async()=>{const r=await api.get(base+'/evidence/'+e.evidence_id);const raw=Uint8Array.from(atob(r.content_base64),c=>c.charCodeAt(0));const u=URL.createObjectURL(new Blob([raw]));const a=document.createElement('a');a.href=u;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);})}>{'Download original'}</button></section>)}</>:<section className="business-empty"><h3>{'Add the first evidence document.'}</h3><p>{'A procedure, policy, operational metrics or review notes can provide useful evidence.'}</p></section>}</>;
}

function ReviewPanel({detail,run,api,lang,busy,perform,refresh,goAssessment,goOverview,goHistory}:{detail:J;run:J|null;api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>;goAssessment:()=>void;goOverview:()=>void;goHistory:()=>void}){
 const o=detail.object,base='/business/objects/'+o.object_id;
 const initial=detail.draft?.run_id===o.latest_run?detail.draft.proposal:run?.analysis?.proposal;
 const [proposal,setProposal]=useState<J|null>(initial?structuredClone(initial):null),[dirty,setDirty]=useState(false),[note,setNote]=useState(''),[reason,setReason]=useState(''),[days,setDays]=useState(7);
 useEffect(()=>{if(initial&&!dirty)setProposal(structuredClone(initial));},[detail.draft?.digest,run?.result_ref?.sha256]);
 const update=(next:J)=>{setProposal(next);setDirty(true);};
 function changeItem(index:number,key:string,value:string){const p=structuredClone(proposal!);p.decision_items[index][key]=value;if(p.reassessment&&['recommendation','conditions','reassessment_conditions'].includes(key)){const impact=p.reassessment.impacts.find((x:J)=>x.decision_item_id===p.decision_items[index].decision_item_id);if(impact&&impact.status!=='AFFECTED'){impact.status='AFFECTED';impact.unknowns=[];}}update(p);}
 if(!proposal)return <section className="business-empty"><h2>{'Review the assessment before making a decision.'}</h2><button className="business-primary" onClick={goAssessment}>{'Open assessment'}</button></section>;
 const stale=o.draft&&o.draft.data_revision!==o.data_revision;
 const published=!dirty&&!stale&&!!o.approval&&o.published_current?.receipt_id===o.approval.receipt_id&&o.draft?.digest===o.published_current?.digest;
 const impactPriority=new Map<string,number>((proposal.reassessment?.impacts||[]).map((x:J)=>[x.decision_item_id,x.status==='AFFECTED'?0:x.status==='UNKNOWN'?1:2] as [string,number]));
 const displayedItems=proposal.decision_items.map((item:J,index:number)=>({item,index})).sort((a:J,b:J)=>(impactPriority.get(a.item.decision_item_id)??3)-(impactPriority.get(b.item.decision_item_id)??3));
 return <><div className="business-section-heading"><div><h2>{'Review the reasoning. Record your judgment.'}</h2><p>{'Edit the AI proposal where needed, then save and approve it. Publishing the official decision is a separate action.'}</p></div></div>{stale&&<div className="business-alert">{'Evidence changed after this draft. Run a new assessment before approval.'}</div>}
 <ReassessmentPanel proposal={proposal} priorItems={run?.comparison_baseline?.decision_items||[]} evidence={detail.evidence} lang={lang}/>
 <form onSubmit={e=>{e.preventDefault();void perform(async()=>{await api.post(base+'/draft',{expected_revision:o.record_revision,run_id:o.latest_run,proposal,change_reason:note});setDirty(false);await refresh();},'Draft saved. You can now record your review decision.');}}>
 <section className="business-card"><Field label={'Decision summary'}><textarea value={proposal.summary} maxLength={2400} onChange={e=>update({...proposal,summary:e.target.value})}/></Field>{proposal.missing_information.length>0&&<div className="business-missing"><strong>{'Missing information'}</strong><ul>{proposal.missing_information.map((s:string,i:number)=><li key={i}>{s}</li>)}</ul></div>}</section>
 <div className="business-review-items">{displayedItems.map(({item,index}:{item:J;index:number},displayIndex:number)=><section className="business-card" key={item.decision_item_id}><p className="business-kicker">{String(displayIndex+1).padStart(2,'0')} · {word(item.perspective,lang)}</p><h3>{item.question}</h3><Field label={'Decision'}><select value={item.recommendation} onChange={e=>changeItem(index,'recommendation',e.target.value)}>{['CONTINUE','REVISE','STOP','EXPAND','NEEDS_INPUT'].map(v=><option key={v} value={v}>{word(v,lang)}</option>)}</select></Field><Field label={'Rationale'}><textarea value={item.rationale} maxLength={2200} onChange={e=>changeItem(index,'rationale',e.target.value)}/></Field><Field label={'Conditions'}><textarea value={item.conditions} maxLength={1600} onChange={e=>changeItem(index,'conditions',e.target.value)}/></Field><Field label={'When to reassess'}><textarea value={item.reassessment_conditions} maxLength={1000} onChange={e=>changeItem(index,'reassessment_conditions',e.target.value)}/></Field><CitationList items={item.citations} evidence={detail.evidence} lang={lang}/></section>)}</div>
 <section className="business-card"><h3>{'Findings and proposed actions'}</h3>{proposal.findings.map((f:J,index:number)=><Field key={f.finding_id} label={word(f.kind,lang)+' · '+f.title}><textarea value={f.description} maxLength={2000} onChange={e=>{const p=structuredClone(proposal);p.findings[index].description=e.target.value;update(p);}}/></Field>)}{proposal.actions.map((a:J,index:number)=><Field key={index} label={a.title}><textarea value={a.description} maxLength={1500} onChange={e=>{const p=structuredClone(proposal);p.actions[index].description=e.target.value;update(p);}}/></Field>)}<Field label={'Review / edit note'}><textarea required maxLength={1600} value={note} onChange={e=>setNote(e.target.value)} placeholder={'What did you check or change?'}/></Field><button className="business-primary" disabled={busy||stale||!note.trim()}>{busy?'Saving…':'Save decision draft'}</button>{dirty&&<small className="business-unsaved">{'You have unsaved changes.'}</small>}</section></form>
 <section className="business-card business-human"><p className="business-kicker">HUMAN DECISION</p><h2>{'How will you treat this draft?'}</h2><p>{'Approval records your decision on the saved draft. It does not publish it or change AWS permissions.'}</p><Field label={'Reason for your decision'}><textarea value={reason} maxLength={1600} onChange={e=>setReason(e.target.value)}/></Field><Field label={'Approval validity (days)'}><input className="business-days" type="number" min={1} max={30} value={days} onChange={e=>setDays(Number(e.target.value))}/></Field><div className="business-button-row">{(['APPROVE','RETURN','REJECT'] as const).map(d=><button key={d} className={d==='APPROVE'?'business-primary':'business-secondary'} disabled={busy||dirty||stale||!o.draft||!reason.trim()} onClick={()=>perform(async()=>{await api.post(base+'/review',{expected_revision:o.record_revision,digest:o.draft.digest,decision:d,reason,valid_days:days});await refresh();},d==='APPROVE'?'Approval recorded. The official decision has not changed.':'Your decision was recorded.')}>{d==='APPROVE'?'Record approval':d==='RETURN'?'Return for revision':'Record rejection'}</button>)}</div>{o.approval&&<div className="business-approval-record"><strong>{'Approved'}</strong><p>{o.approval.approver_name} · {date(o.approval.at)}</p><p>{o.approval.reason}</p><small>{'Valid until: '}{date(o.approval.expires_at)}</small></div>}</section>
 {published?<section className="business-card business-publication-complete" aria-label="Publication complete"><div role="status"><p className="business-kicker">{'PUBLICATION COMPLETE'}</p><h2>{'Your decision is now the official version.'}</h2><p>{'Published by'}: {o.published_current.publisher_name} · {date(o.published_current.at)}</p><p>{'Publication is complete. No waiting or another publish click is needed. Next, view the official decision or open its history and download the record.'}</p></div><div className="business-button-row"><button type="button" className="business-primary" onClick={goOverview}>{'View official decision'}</button><button type="button" className="business-secondary" onClick={goHistory}>{'View history and records'}</button></div></section>:<section className="business-card business-publish"><div><p className="business-kicker">EXPLICIT PUBLICATION</p><h2>{'Publish the official decision.'}</h2><p>{'Update this workspace’s official decision and retain its publisher and evidence. AWS runtime application is separate.'}</p></div><button className="business-primary" disabled={busy||dirty||stale||!o.approval||o.published_current?.receipt_id===o.approval?.receipt_id} onClick={()=>perform(async()=>{await api.post(base+'/publish',{expected_revision:o.record_revision,receipt_id:o.approval.receipt_id});await refresh();},'Official decision published. Find it in Overview and History.')}>{'Publish this decision'}</button></section>}
 <AuthorityPanel detail={detail} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh}/></>;
}

export function ConnectionSelector({detail,api,lang,busy,perform,refresh}:{detail:J;api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>}){
 const o=detail.object,registered:J[]=detail.registered_adapters||[],[key,setKey]=useState(''),[reason,setReason]=useState('');
 const selected=registered.find(v=>v.adapter_id+'|'+v.connection_id===key);
 if(o.execution_connection)return <p role="alert">{'The saved connection no longer matches its registration. New delegation is blocked.'}</p>;
 if(!registered.length)return null;
 return <details className="business-details"><summary>{'Select a matching AWS connection (optional)'}</summary><p>{'Choose an execution connection only when it applies to this business. Selecting it does not grant execution authority.'}</p><Field label={'Execution connection for this business'}><select value={key} onChange={e=>setKey(e.target.value)}><option value="">{'No AWS execution connection'}</option>{registered.map(v=><option key={v.adapter_id+'|'+v.connection_id} value={v.adapter_id+'|'+v.connection_id}>{v.adapter_id} · {v.target_account_id} · {v.connection_id}</option>)}</select></Field>{selected&&<><Field label={'Why this connection applies to this business'}><textarea value={reason} maxLength={1600} onChange={e=>setReason(e.target.value)}/></Field><button type="button" className="business-secondary" disabled={busy||!reason.trim()} onClick={()=>perform(async()=>{await api.post('/business/objects/'+o.object_id+'/connection',{expected_revision:o.record_revision,adapter_id:selected.adapter_id,adapter_version:selected.adapter_version,connection_id:selected.connection_id,registration_hash:selected.registration_hash,reason});await refresh();},'Execution connection saved. No execution authority was granted.')}>{'Save connection for this business'}</button></>}</details>;
}

export function AuthorityPanel({detail,api,lang,busy,perform,refresh}:{detail:J;api:BusinessApi;lang:Lang;busy:boolean;perform:(f:()=>Promise<any>,s?:string)=>Promise<any>;refresh:()=>Promise<void>}){
 const o=detail.object,base='/business/objects/'+o.object_id,adapters:J[]=detail.available_adapters||[];
 const latestInvocation=[...(detail.invocations||[])].sort((a:J,b:J)=>String(a.updated_at).localeCompare(String(b.updated_at))).at(-1)||null;
 const [adapterKey,setAdapterKey]=useState(adapters[0]?adapters[0].adapter_id+'|'+adapters[0].connection_id:''),[profileId,setProfileId]=useState(adapters[0]?.profiles?.[0]?.profile_id||'MAINTAIN'),[reason,setReason]=useState(''),[days,setDays]=useState(7),[stopReason,setStopReason]=useState(''),[invocation,setInvocation]=useState<J|null>(latestInvocation),[invokeRequest,setInvokeRequest]=useState('');
 useEffect(()=>{if(!adapters.some(a=>a.adapter_id+'|'+a.connection_id===adapterKey)&&adapters[0]){setAdapterKey(adapters[0].adapter_id+'|'+adapters[0].connection_id);setProfileId(adapters[0].profiles[0]?.profile_id||'MAINTAIN');}},[detail.available_adapters]);
 useEffect(()=>{if(latestInvocation&&(!invocation||latestInvocation.updated_at>invocation.updated_at))setInvocation(latestInvocation);},[latestInvocation?.operation_id,latestInvocation?.updated_at]);
 useEffect(()=>{if(!invocation||invocation.status==='EXECUTED')return;const operationId=invocation.operation_id;let live=true,timer:number;async function poll(){try{const next=await api.get(base+'/invocations/'+operationId);if(!live)return;setInvocation(next);if(next.status!=='EXECUTED')timer=window.setTimeout(poll,next.status==='UNKNOWN'?10000:3000);}catch{if(live)timer=window.setTimeout(poll,10000);}}timer=window.setTimeout(poll,invocation.status==='UNKNOWN'?10000:3000);return()=>{live=false;clearTimeout(timer);};},[invocation?.operation_id,invocation?.status,base]);
 const adapter=adapters.find(a=>a.adapter_id+'|'+a.connection_id===adapterKey)||adapters[0],profile=adapter?.profiles?.find((p:J)=>p.profile_id===profileId)||adapter?.profiles?.[0];
 const approval=o.delegation_approval?.publication_id===o.published_current?.publication_id?o.delegation_approval:null,control=o.authority_control;
 const revoking=['STOP_REQUESTED','UNKNOWN'].includes(control?.status),suspended=control?.status==='SUSPENDED_CONFIRMED';
 const unresolved=['APPLYING','CANARY','UNKNOWN'].includes(o.latest_application?.status)||revoking;
 const applied=o.applied_binding?.runtime_authority_active===true&&o.applied_binding?.publication_id===o.published_current?.publication_id&&control?.status==='VERIFIED'&&control?.entry_status==='OPEN'&&control?.runtime_authority_active===true;
 const activeProfile=adapter?.profiles?.find((p:J)=>p.profile_id===o.applied_binding?.profile_id)||profile,allowed:string[]=activeProfile?.allowed_request_ids||[];
 useEffect(()=>{if(!invokeRequest&&allowed[0])setInvokeRequest(allowed[0]);},[allowed.join('|')]);
 if(!o.published_current)return <section className="business-card business-authority"><p className="business-kicker">SEPARATE AWS AUTHORITY</p><h2>{'AWS delegation starts only after official publication.'}</h2><p>{'Business approval and official publication never grant AWS runtime authority.'}</p></section>;
 if(!adapter)return <section className="business-card business-authority business-authority-closed"><p className="business-kicker">SEPARATE AWS AUTHORITY</p><h2>{'No AWS execution adapter is connected.'}</h2><p>{'The business decision remains official but is not applied to AWS.'}</p><div className="business-application-state"><span>{'AWS runtime authority'}</span><strong>{word(o.application_status||'NOT_APPLIED',lang)}</strong></div><ConnectionSelector detail={detail} api={api} lang={lang} busy={busy} perform={perform} refresh={refresh}/></section>;
 return <section className="business-card business-authority"><p className="business-kicker">SEPARATE AWS AUTHORITY · REGISTERED ADAPTER</p><h2>{'Separately delegate and apply a registered boundary.'}</h2><p className="business-authority-warning">{'This is separate from business approval. The candidate starts closed, and the current AppliedBinding is retained until verification succeeds.'}</p>{adapters.length>1&&<Field label={'Registered connection'}><select value={adapterKey} onChange={e=>{setAdapterKey(e.target.value);const next=adapters.find(a=>a.adapter_id+'|'+a.connection_id===e.target.value);setProfileId(next?.profiles?.[0]?.profile_id||'MAINTAIN');}}>{adapters.map(a=><option key={a.adapter_id+'|'+a.connection_id} value={a.adapter_id+'|'+a.connection_id}>{a.adapter_id} · {a.connection_id}</option>)}</select></Field>}<dl className="business-binding"><div><dt>Adapter</dt><dd>{adapter.adapter_id} · {adapter.adapter_version}</dd></div><div><dt>Connection</dt><dd>{adapter.connection_id}</dd></div><div><dt>Target</dt><dd>{adapter.target_account_id} · {adapter.target_region}</dd></div><div><dt>Runtime release</dt><dd>{adapter.release_id} · version {adapter.runtime_version}</dd></div><div><dt>Mode</dt><dd>{adapter.connection_mode}</dd></div></dl>
 {revoking&&<div className="business-application-result unknown" role="status"><Status value={control.status==='UNKNOWN'?'STOP_UNKNOWN':'STOP_REQUESTED'} lang={lang}/><h3>{'Entry closed. AWS revocation verification is still running.'}</h3><ol><li>{'New execution entry: closed'}</li><li>{control.policy_status==='REMOVED'?'Owned Policy: removal confirmed':'Owned Policy: removal not yet confirmed'}</li><li>{control.deny_status==='CONFIRMED'?'Live DENY: confirmed':'Live DENY: not confirmed'}</li></ol><p>{control.status==='UNKNOWN'?'This is not reported as suspended. Recovery retries the same registered request automatically.':'You do not need to keep this page open. It changes to “Suspension confirmed” only after live proof.'}</p></div>}
 {suspended&&<div className="business-application-result recovered_closed" role="status"><Status value="SUSPENDED_CONFIRMED" lang={lang}/><h3>{'AWS authority suspension is confirmed.'}</h3><p>{'The product entry is closed, the owned Policy is absent, and every registered request has a live DENY result. History is retained.'}</p></div>}
 {!applied&&invocation&&<div className="business-delegation-record" role="status"><strong>{invocation.status==='EXECUTED'?'Accepted invocation confirmed':invocation.status==='UNKNOWN'?'Recovering accepted invocation':'Processing invocation accepted before closure'}</strong><p>{invocation.result?`${invocation.result.outcome} · ${invocation.result.request_id}`:invocation.error||'The same operation ID remains tracked separately from the new-entry gate.'}</p></div>}
 {!revoking&&(!approval?<><Field label={'Registered delegation profile'}><select value={profile?.profile_id||profileId} onChange={e=>setProfileId(e.target.value)}>{adapter.profiles.map((p:J)=><option key={p.profile_id} value={p.profile_id}>{p.profile_id} · {p.allowed_request_count} finite allowed requests</option>)}</select></Field>{profile&&<details className="business-details"><summary>{'Review the fixed boundary'}</summary><pre>{JSON.stringify(profile.boundary,null,2)}</pre></details>}<Field label={'Reason for AWS delegation'}><textarea maxLength={1600} value={reason} onChange={e=>setReason(e.target.value)}/></Field><Field label={'Delegation validity (days)'}><input className="business-days" type="number" min={1} max={30} value={days} onChange={e=>setDays(Number(e.target.value))}/></Field><button type="button" className="business-primary" disabled={busy||unresolved||!reason.trim()} onClick={()=>perform(async()=>{await api.post(base+'/delegation',{expected_revision:o.record_revision,publication_id:o.published_current.publication_id,publication_digest:o.published_current.digest,adapter_id:adapter.adapter_id,adapter_version:adapter.adapter_version,connection_id:adapter.connection_id,profile_id:profile.profile_id,reason,valid_days:days});await refresh();},'AWS delegation approved separately. It is not applied yet.')}>{'Approve AWS delegation separately'}</button></>:<div className="business-delegation-record"><Status value="DELEGATION_APPROVED" lang={lang}/><p>{'This receipt binds the publication, connection, Runtime, finite request set and policy hash. Runtime authority is not active yet.'}</p><dl className="business-binding"><div><dt>Receipt</dt><dd>{approval.receipt_id}</dd></div><div><dt>Profile</dt><dd>{approval.profile_id}</dd></div><div><dt>Expires</dt><dd>{date(approval.expires_at)}</dd></div></dl>{!unresolved&&!applied&&<button type="button" className="business-primary" disabled={busy} onClick={()=>perform(async()=>{await api.post(base+'/applications',{expected_revision:o.record_revision,delegation_receipt_id:approval.receipt_id});await refresh();},'Application started. It remains unapplied until verification completes.')}>{'Start closed application and verification'}</button>}</div>)}
 {applied&&<div className="business-application-result verified"><Status value="VERIFIED" lang={lang}/><h3>{'Only the current finite authority can execute.'}</h3><p>{'Expires: '}{date(o.applied_binding.delegation_expires_at)}</p>{allowed.length>0&&<><Field label={'Registered protected request'}><select value={invokeRequest} onChange={e=>setInvokeRequest(e.target.value)}>{allowed.map(id=><option key={id} value={id}>{id}</option>)}</select></Field><button type="button" className="business-primary" disabled={busy||!invokeRequest||!!(invocation&&invocation.status!=='EXECUTED')} onClick={()=>void perform(async()=>{const next=await api.invoke(base+'/invocations',invokeRequest);setInvocation(next);},'Invocation accepted. This page will check the result automatically.')}>{'Run with current authority'}</button></>}{invocation&&<div className="business-delegation-record" role="status"><strong>{invocation.status==='EXECUTED'?'Execution confirmed':invocation.status==='UNKNOWN'?'Recovering result':'Execution queued'}</strong><p>{invocation.result?`${invocation.result.outcome} · ${invocation.result.request_id}`:invocation.error||'Processing continues if you leave this page.'}</p></div>}<hr/><h3>{'Stop this AWS authority'}</h3><p>{'The new-entry gate closes with the stop request. Suspension is not reported complete until Policy removal and live DENY are confirmed.'}</p><Field label={'Reason for stopping'}><textarea maxLength={1600} value={stopReason} onChange={e=>setStopReason(e.target.value)}/></Field><button type="button" className="business-secondary" disabled={busy||!stopReason.trim()} onClick={()=>void perform(async()=>{await api.post(base+'/revocations',{expected_revision:o.record_revision,application_id:o.applied_binding.application_id,reason:stopReason});await refresh();},'New execution is closed and AWS revocation verification has started.')}>{'Close entry and begin suspension'}</button></div>}
 {o.latest_application&&!revoking&&!suspended&&<div className={'business-application-result '+String(o.latest_application.status).toLowerCase()}><Status value={o.latest_application.status} lang={lang}/><p>{o.latest_application.status==='UNKNOWN'?'The outcome is unconfirmed. The writer lock is retained, blocking another application until reconciliation.':applied?'The fixed canary outcomes were verified and this publication is now the AppliedBinding.':'The AppliedBinding has not been switched.'}</p><small>{o.latest_application.application_id}</small></div>}
 </section>;
}
